def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v2 == 0:
        return None

    percentage = (v1 / v2) * 100

    return {
        "value": percentage,
        "trace": {
            "consumer_packaging_capital_spending": v1,
            "total_capital_spending": v2,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": "percent",
                "unit": "percentage"
            }
        }
    }
